import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

import type { Cue } from '@/lib/train';

/**
 * Timer beeps (#80): a tick for 3-2-1, a higher "go" at each interval change, a triple for "done".
 * Generated by `scripts/gen-beeps.mjs`. They play over music (ducking it) and in silent mode, since the
 * timer exists to be heard with the phone on the floor.
 */
const SOURCES: Record<Cue, number> = {
  tick: require('../../assets/sounds/tick.wav'),
  go: require('../../assets/sounds/go.wav'),
  done: require('../../assets/sounds/done.wav'),
};

let players: Partial<Record<Cue, AudioPlayer>> | null = null;

function load(): Partial<Record<Cue, AudioPlayer>> {
  if (players) return players;
  players = {};
  try {
    void setAudioModeAsync({ playsInSilentMode: true, interruptionMode: 'duckOthers' }).catch(() => {});
    for (const cue of Object.keys(SOURCES) as Cue[]) players[cue] = createAudioPlayer(SOURCES[cue]);
  } catch {
    // No audio support: the cues are still shown and felt.
  }
  return players;
}

/** Preload the players (call when a timer starts, so the first tick isn't late). */
export function prepareSounds(): void {
  load();
}

export function playCue(cue: Cue): void {
  const p = load()[cue];
  if (!p) return;
  try {
    void p
      .seekTo(0)
      .then(() => p.play())
      .catch(() => {});
  } catch {
    // ignore: a missed beep must never break the timer
  }
}
